from __future__ import annotations

"""Configuration for one Meta app's webhook receiver.

A single deployment can host more than one Graph app: each app has its own
secret (used to sign and verify webhook deliveries) and its own verify token
(used during the one-time subscription handshake). This module holds that
configuration and a tiny registry so the entry point can look an app up by
its identifier.

Secrets are kept as bytes because they feed directly into keyed hashing; the
verify token is a short opaque string the app owner pastes into both the
dashboard and this config.
"""

from dataclasses import dataclass


@dataclass(frozen=True)
class AppConfig:
    """Per-app webhook configuration.

    Attributes:
        app_id: The Graph application id this config belongs to.
        app_secret: The app secret, as bytes, used for delivery signatures.
        verify_token: The shared token echoed during subscription setup.
        object_type: The subscription object (``page``, ``instagram``, ...).
    """

    app_id: str
    app_secret: bytes
    verify_token: str
    object_type: str = "page"

    def __post_init__(self) -> None:
        if not self.app_id:
            raise ValueError("app_id is required")
        if not isinstance(self.app_secret, (bytes, bytearray)):
            raise TypeError("app_secret must be bytes")
        if not self.app_secret:
            raise ValueError("app_secret must not be empty")
        if not self.verify_token:
            raise ValueError("verify_token is required")

    @property
    def secret_bytes(self) -> bytes:
        return bytes(self.app_secret)


def app_config(
    app_id: str,
    app_secret: bytes | str,
    verify_token: str,
    object_type: str = "page",
) -> AppConfig:
    """Build an :class:`AppConfig`, accepting a str or bytes secret."""

    if isinstance(app_secret, str):
        app_secret = app_secret.encode("utf-8")
    return AppConfig(
        app_id=app_id,
        app_secret=bytes(app_secret),
        verify_token=verify_token,
        object_type=object_type,
    )


class AppRegistry:
    """Holds the configuration for every app this receiver serves."""

    def __init__(self) -> None:
        self._apps: dict[str, AppConfig] = {}

    def register(self, config: AppConfig) -> None:
        self._apps[config.app_id] = config

    def get(self, app_id: str) -> AppConfig | None:
        return self._apps.get(app_id)

    def require(self, app_id: str) -> AppConfig:
        config = self._apps.get(app_id)
        if config is None:
            raise KeyError(f"no app registered for id {app_id!r}")
        return config

    def __contains__(self, app_id: str) -> bool:
        return app_id in self._apps

    def __len__(self) -> int:
        return len(self._apps)

