from __future__ import annotations

"""In-memory audit trail for webhook deliveries.

Every inbound delivery — accepted or rejected — is recorded with a reason so
on-call can answer "did we act on this, and if not, why?" without grepping
application logs. The store is intentionally simple: an append-only list of
records the tests and dashboards can read back.

Records never contain the app secret. They may carry the delivery id and the
verdict reason code so a spike of one rejection reason is easy to spot.
"""

import time
from dataclasses import dataclass, field
from typing import Optional


ACCEPTED = "accepted"
REJECTED = "rejected"


@dataclass(frozen=True)
class AuditRecord:
    """One line in the audit trail."""

    outcome: str
    reason: str
    delivery_id: Optional[str] = None
    algorithm: Optional[str] = None
    at: float = field(default_factory=time.time)

    @property
    def accepted(self) -> bool:
        return self.outcome == ACCEPTED


class AuditLog:
    """Append-only record of delivery outcomes."""

    def __init__(self) -> None:
        self._records: list[AuditRecord] = []

    def record_accept(
        self,
        reason: str = "ok",
        delivery_id: Optional[str] = None,
        algorithm: Optional[str] = None,
    ) -> AuditRecord:
        record = AuditRecord(ACCEPTED, reason, delivery_id, algorithm)
        self._records.append(record)
        return record

    def record_reject(
        self,
        reason: str,
        delivery_id: Optional[str] = None,
        algorithm: Optional[str] = None,
    ) -> AuditRecord:
        record = AuditRecord(REJECTED, reason, delivery_id, algorithm)
        self._records.append(record)
        return record

    def records(self) -> tuple[AuditRecord, ...]:
        return tuple(self._records)

    def last(self) -> Optional[AuditRecord]:
        return self._records[-1] if self._records else None

    def count(self, outcome: Optional[str] = None) -> int:
        if outcome is None:
            return len(self._records)
        return sum(1 for r in self._records if r.outcome == outcome)

    def reasons(self) -> list[str]:
        return [r.reason for r in self._records]

    def clear(self) -> None:
        self._records.clear()

