from __future__ import annotations

"""Test/tooling helpers for crafting webhook deliveries.

These build :class:`RawRequest` objects the way Meta's edge would: a raw JSON
body plus a signature header computed over those exact bytes. The helpers are
generic and correct — they sign whatever bytes you hand them under whatever
algorithm you name. They are used to mint both legitimate deliveries and the
adversarial ones (downgraded, tampered, re-serialized) the receiver must
withstand.

Nothing here makes a trust decision; that is the receiver's job.
"""

import hashlib
import hmac
import json
from typing import Any, Mapping

from raw_request import RawRequest, build_request

HEADER_SHA1 = "X-Hub-Signature"
HEADER_SHA256 = "X-Hub-Signature-256"

_DIGESTS = {"sha1": hashlib.sha1, "sha256": hashlib.sha256}


def sign_bytes(secret: bytes, body: bytes, algorithm: str = "sha256") -> str:
    """Return the ``<alg>=<hex>`` header value for ``body`` under ``secret``."""

    constructor = _DIGESTS[algorithm]
    digest = hmac.new(secret, body, constructor).hexdigest()
    return f"{algorithm}={digest}"


def signed_post(
    secret: bytes,
    payload: dict[str, Any],
    *,
    algorithm: str = "sha256",
    body_bytes: bytes | None = None,
    extra_headers: Mapping[str, str] | None = None,
) -> RawRequest:
    """Build a POST whose signature header covers the exact body bytes.

    When ``body_bytes`` is supplied it is used verbatim as the request body and
    the signature is computed over it; otherwise the payload is serialized with
    a compact, stable separator set first.
    """

    if body_bytes is None:
        body_bytes = json.dumps(payload, separators=(",", ":")).encode("utf-8")

    header_name = HEADER_SHA256 if algorithm == "sha256" else HEADER_SHA1
    headers = {header_name: sign_bytes(secret, body_bytes, algorithm)}
    if extra_headers:
        headers.update(extra_headers)
    return build_request("POST", body=body_bytes, headers=headers)


def unsigned_post(payload: dict[str, Any], *, body_bytes: bytes | None = None) -> RawRequest:
    """Build a POST with no signature header at all."""

    if body_bytes is None:
        body_bytes = json.dumps(payload, separators=(",", ":")).encode("utf-8")
    return build_request("POST", body=body_bytes, headers={})


def post_with_header(
    payload: dict[str, Any],
    header_name: str,
    header_value: str,
    *,
    body_bytes: bytes | None = None,
) -> RawRequest:
    """Build a POST with an arbitrary signature header value."""

    if body_bytes is None:
        body_bytes = json.dumps(payload, separators=(",", ":")).encode("utf-8")
    return build_request("POST", body=body_bytes, headers={header_name: header_value})


def handshake_get(
    *, mode: str = "subscribe", token: str = "", challenge: str = "echo-123"
) -> RawRequest:
    """Build a GET subscription handshake request."""

    query = {
        "hub.mode": mode,
        "hub.verify_token": token,
        "hub.challenge": challenge,
    }
    return build_request("GET", body=b"", query=query)


def sample_page_payload(delivery_id: str | None = None) -> dict[str, Any]:
    """A representative Page ``feed`` change delivery."""

    payload: dict[str, Any] = {
        "object": "page",
        "entry": [
            {
                "id": "page-1",
                "time": 1700000000,
                "changes": [
                    {"field": "feed", "value": {"item": "status", "post_id": "p1"}}
                ],
            }
        ],
    }
    if delivery_id is not None:
        payload["delivery_id"] = delivery_id
    return payload

