from __future__ import annotations

"""Routes verified webhook events to registered handlers.

Once a delivery has been authenticated and parsed, the dispatcher walks the
entries and fans each change or messaging event out to whatever handlers were
registered for that combination of object type and field. Handlers are plain
callables; the dispatcher only cares that they were registered and records how
many it invoked.

The dispatcher is deliberately side-effect heavy: handlers post to downstream
queues, update caches, and send replies. That is exactly why nothing should
reach it until the delivery has been proven authentic — a single call here is
an observable action on behalf of the page or account.
"""

from collections import defaultdict
from dataclasses import dataclass, field
from typing import Callable, DefaultDict

from event_models import ChangeEvent, Entry, MessagingEvent, WebhookEvent

# A change handler receives (entry, change_event).
ChangeHandler = Callable[[Entry, ChangeEvent], None]
# A messaging handler receives (entry, messaging_event).
MessagingHandler = Callable[[Entry, MessagingEvent], None]


@dataclass
class DispatchReport:
    """Summary of one dispatch pass."""

    handled_changes: int = 0
    handled_messaging: int = 0
    unrouted: int = 0
    invoked: list[str] = field(default_factory=list)

    @property
    def total_handled(self) -> int:
        return self.handled_changes + self.handled_messaging

    def note(self, label: str) -> None:
        self.invoked.append(label)


class EventDispatcher:
    """Registry of handlers keyed by object type and field name."""

    def __init__(self) -> None:
        self._change_handlers: DefaultDict[str, dict[str, list[ChangeHandler]]] = defaultdict(dict)
        self._messaging_handlers: DefaultDict[str, list[MessagingHandler]] = defaultdict(list)
        self._dispatch_count = 0

    # -- registration -----------------------------------------------------

    def on_change(self, object_type: str, field_name: str, handler: ChangeHandler) -> None:
        """Register a handler for a specific object type and change field."""

        by_field = self._change_handlers[object_type]
        by_field.setdefault(field_name, []).append(handler)

    def on_messaging(self, object_type: str, handler: MessagingHandler) -> None:
        """Register a handler for messaging events on an object type."""

        self._messaging_handlers[object_type].append(handler)

    # -- dispatch ---------------------------------------------------------

    def dispatch(self, event: WebhookEvent) -> DispatchReport:
        """Fan a parsed event out to the registered handlers."""

        self._dispatch_count += 1
        report = DispatchReport()
        object_type = event.object_type

        for entry in event.entries:
            self._dispatch_changes(object_type, entry, report)
            self._dispatch_messaging(object_type, entry, report)
        return report

    def _dispatch_changes(self, object_type: str, entry: Entry, report: DispatchReport) -> None:
        field_map = self._change_handlers.get(object_type, {})
        for change in entry.changes:
            handlers = field_map.get(change.field)
            if not handlers:
                report.unrouted += 1
                continue
            for handler in handlers:
                handler(entry, change)
                report.handled_changes += 1
                report.note(f"change:{object_type}:{change.field}")

    def _dispatch_messaging(self, object_type: str, entry: Entry, report: DispatchReport) -> None:
        handlers = self._messaging_handlers.get(object_type, [])
        for message in entry.messaging:
            if not handlers:
                report.unrouted += 1
                continue
            for handler in handlers:
                handler(entry, message)
                report.handled_messaging += 1
                report.note(f"messaging:{object_type}")

    # -- introspection ----------------------------------------------------

    @property
    def dispatch_count(self) -> int:
        """How many times :meth:`dispatch` has been entered."""

        return self._dispatch_count

    def has_change_handler(self, object_type: str, field_name: str) -> bool:
        return bool(self._change_handlers.get(object_type, {}).get(field_name))

    def has_messaging_handler(self, object_type: str) -> bool:
        return bool(self._messaging_handlers.get(object_type))

    def reset_counts(self) -> None:
        self._dispatch_count = 0


class RecordingHandler:
    """A test-friendly handler that records every call it receives."""

    def __init__(self) -> None:
        self.calls: list[tuple] = []

    def __call__(self, entry: Entry, event) -> None:
        self.calls.append((entry, event))

    @property
    def call_count(self) -> int:
        return len(self.calls)

    @property
    def called(self) -> bool:
        return bool(self.calls)

