from __future__ import annotations

"""De-duplication of webhook deliveries.

Meta retries a delivery if the receiver does not answer quickly enough, so the
same logical event can arrive more than once. When a delivery carries an id we
remember it and treat a repeat as a duplicate, letting the entry point skip
re-dispatching events the handlers already saw. The window is bounded so memory
does not grow without limit on a busy endpoint.

This is a secondary safeguard layered after signature verification — it never
decides authenticity, only freshness.
"""

from collections import OrderedDict
from typing import Optional


class ReplayGuard:
    """Tracks recently seen delivery ids to suppress duplicates."""

    def __init__(self, capacity: int = 1024) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._seen: "OrderedDict[str, bool]" = OrderedDict()

    def seen(self, delivery_id: Optional[str]) -> bool:
        """True if this delivery id was already recorded."""

        if delivery_id is None:
            return False
        return delivery_id in self._seen

    def remember(self, delivery_id: Optional[str]) -> None:
        """Record a delivery id, evicting the oldest if at capacity."""

        if delivery_id is None:
            return
        if delivery_id in self._seen:
            self._seen.move_to_end(delivery_id)
            return
        self._seen[delivery_id] = True
        while len(self._seen) > self.capacity:
            self._seen.popitem(last=False)

    def check_and_remember(self, delivery_id: Optional[str]) -> bool:
        """Return True if fresh (and record it); False if a duplicate.

        A delivery with no id is always treated as fresh because there is
        nothing to de-duplicate on.
        """

        if delivery_id is None:
            return True
        if delivery_id in self._seen:
            self._seen.move_to_end(delivery_id)
            return False
        self.remember(delivery_id)
        return True

    def size(self) -> int:
        return len(self._seen)

    def clear(self) -> None:
        self._seen.clear()

