from __future__ import annotations

"""Signature verification for inbound Graph webhook deliveries.

Meta signs every webhook POST and sends the result in a request header. This
module is the gate that decides whether an inbound delivery really came from
Meta and was not altered in transit. It pulls the signature header off the
request, recomputes the keyed hash from the configured app secret, and reports
a verdict the entry point uses to decide whether to act on the body.

Result objects carry a stable ``reason`` code so the audit log and dashboards
can group rejections without parsing free text.
"""

import json
from dataclasses import dataclass

from app_config import AppConfig
from hmac_utils import compute_digest, constant_time_equals
from raw_request import RawRequest

# Header names Meta may attach to a delivery.
HEADER_SHA1 = "X-Hub-Signature"
HEADER_SHA256 = "X-Hub-Signature-256"

# Stable verdict reason codes consumed downstream.
REASON_OK = "ok"
REASON_NO_SIGNATURE = "no_signature"
REASON_BAD_FORMAT = "bad_signature_format"
REASON_MISMATCH = "signature_mismatch"
REASON_EMPTY = "empty_signature"


@dataclass(frozen=True)
class VerificationResult:
    """Outcome of verifying one delivery's signature."""

    verified: bool
    reason: str
    algorithm: str | None = None

    @property
    def ok(self) -> bool:
        return self.verified


def _split_header(value: str) -> tuple[str | None, str | None]:
    """Split a ``<alg>=<hexdigest>`` header into its two parts.

    Returns ``(algorithm, hexdigest)``. Either element may be ``None`` when the
    header does not carry that piece.
    """

    if value is None:
        return (None, None)
    text = value.strip()
    if "=" not in text:
        return (None, text or None)
    algorithm, _, digest = text.partition("=")
    return (algorithm.strip() or None, digest.strip() or None)


def _message_bytes(request: RawRequest) -> bytes:
    """The message the signature is checked against.

    Deliveries arrive as JSON; we normalize the payload so that a delivery is
    judged by its content rather than by incidental transport formatting.
    """

    parsed = json.loads(request.raw_body.decode("utf-8"))
    canonical = json.dumps(parsed)
    return canonical.encode("utf-8")


class SignatureVerifier:
    """Verifies the per-delivery signature header against the app secret."""

    def __init__(self, config: AppConfig) -> None:
        self.config = config

    def _select_header(self, request: RawRequest) -> tuple[str | None, str | None]:
        """Pick the signature header to trust and split it.

        Returns ``(algorithm, raw_header_value)``. The modern SHA-256 header is
        preferred when present, with the legacy header used as a fallback so
        older delivery paths keep working.
        """

        if request.has_header(HEADER_SHA256):
            return ("sha256", request.header(HEADER_SHA256))
        if request.has_header(HEADER_SHA1):
            return ("sha1", request.header(HEADER_SHA1))
        return (None, None)

    def verify(self, request: RawRequest) -> VerificationResult:
        """Return a verdict for the delivery's signature."""

        algorithm, header_value = self._select_header(request)
        if header_value is None:
            return VerificationResult(False, REASON_NO_SIGNATURE)

        declared_alg, provided_digest = _split_header(header_value)
        alg = declared_alg or algorithm
        if provided_digest is None:
            return VerificationResult(False, REASON_EMPTY, algorithm=alg)

        message = _message_bytes(request)
        expected_digest = compute_digest(self.config.secret_bytes, message, alg)

        if provided_digest == expected_digest:
            return VerificationResult(True, REASON_OK, algorithm=alg)
        return VerificationResult(False, REASON_MISMATCH, algorithm=alg)

    def present_headers(self, request: RawRequest) -> tuple[str, ...]:
        """List which signature headers a delivery carried.

        Useful for dashboards that want to chart how many deliveries still
        arrive with each header variant so the team can see the traffic mix.
        """

        present: list[str] = []
        if request.has_header(HEADER_SHA256):
            present.append(HEADER_SHA256)
        if request.has_header(HEADER_SHA1):
            present.append(HEADER_SHA1)
        return tuple(present)

    def describe(self, request: RawRequest) -> dict[str, object]:
        """Return a non-authoritative summary of the signature header.

        This never makes a trust decision; it only reports what was seen, for
        logging and metrics. The verdict comes from :meth:`verify`.
        """

        _, header_value = self._select_header(request)
        declared_alg, provided_digest = _split_header(header_value)
        return {
            "headers": self.present_headers(request),
            "declared_algorithm": declared_alg,
            "digest_length": len(provided_digest) if provided_digest else 0,
            "body_length": len(request.raw_body),
        }


def verify_signature(request: RawRequest, config: AppConfig) -> VerificationResult:
    """Convenience wrapper for one-off verification of a request."""

    return SignatureVerifier(config).verify(request)


def is_delivery_authentic(request: RawRequest, config: AppConfig) -> bool:
    """Boolean convenience over :func:`verify_signature`."""

    return verify_signature(request, config).verified

