from __future__ import annotations

"""The webhook subscription verification handshake (GET).

When an app owner subscribes a callback URL in the Graph dashboard, Meta sends
a one-time GET request carrying three query parameters:

* ``hub.mode``         — the literal ``subscribe`` for a subscription request.
* ``hub.verify_token`` — the token the owner configured on both ends.
* ``hub.challenge``    — a random value the receiver must echo back verbatim.

The receiver proves it owns the endpoint by returning the challenge *only*
when the mode is correct and the verify token matches the configured one. Any
other combination is refused so an unrelated caller cannot confirm a
subscription on the app's behalf.
"""

from dataclasses import dataclass

from app_config import AppConfig
from raw_request import RawRequest

MODE_SUBSCRIBE = "subscribe"

PARAM_MODE = "hub.mode"
PARAM_TOKEN = "hub.verify_token"
PARAM_CHALLENGE = "hub.challenge"


@dataclass(frozen=True)
class HandshakeResult:
    """Outcome of a subscription handshake.

    On success ``accepted`` is True and ``challenge`` holds the value to echo
    back to Meta. On failure ``accepted`` is False, ``challenge`` is None, and
    ``reason`` explains why.
    """

    accepted: bool
    challenge: str | None = None
    reason: str = "ok"


class SubscriptionVerifier:
    """Validates the GET subscription handshake against the app config."""

    def __init__(self, config: AppConfig) -> None:
        self.config = config

    def verify(self, request: RawRequest) -> HandshakeResult:
        mode = request.query_param(PARAM_MODE)
        token = request.query_param(PARAM_TOKEN)
        challenge = request.query_param(PARAM_CHALLENGE)

        if mode != MODE_SUBSCRIBE:
            return HandshakeResult(False, reason="bad_mode")
        if token is None or token == "":
            return HandshakeResult(False, reason="missing_token")
        if token != self.config.verify_token:
            return HandshakeResult(False, reason="token_mismatch")
        if challenge is None or challenge == "":
            return HandshakeResult(False, reason="missing_challenge")
        return HandshakeResult(True, challenge=challenge, reason="ok")


def verify_subscription(request: RawRequest, config: AppConfig) -> HandshakeResult:
    """Convenience wrapper for one-off handshake verification."""

    return SubscriptionVerifier(config).verify(request)

